module_state.kujo.source:
mut global_value := 7
export func factory(relay, use_sort) {
 mut count := 0
 func step(write) {
  if write {
   global_value = 9
   count += 1
   if use_sort { sort_by([step,step],relay) } else { relay(step) }
  }
  return [global_value,count]
 }
 return step
}

