journal_probe.kujo.source:
func helper(seed) { return seed }
export func make_work() {
    let seed := 1
    func work(count) {
        mut i := 0
        mut total := 0
        while i < count { total += helper(seed) i += 1 }
        return total
    }
    return work
}

